{
  "scope": {
    "text_used": "The supplied Greek of sections 1–3, without alteration.",
    "status": "Syntactic investigation only; no translation approval or publication authority.",
    "external_evidence": "No lexicon, manuscript, or scholarly parallel has been consulted. The historical English consultation is not treated as evidence for Greek syntax.",
    "confidence_scale": "Qualitative confidence in an analysis from the supplied text, not a calibrated probability."
  },
  "finding": "A resumptive undertaking-infinitive and an elliptical concessive clause are possible hypotheses. The strongest unchanged-text allocation takes τοῦδε with χάριν, μή with μεταδοῦναι, and the nominative descriptions with an omitted copula after conditional ἄν. That allocation does not by itself establish the infinitive's construction or the relationship between οὐδέ and μή. A complete, defensible reading therefore remains unestablished.",
  "oath_context": [
    {
      "section": "1",
      "observation": "The procedure expressly distinguishes prohibited swearing, μὴ ὁρκίσαι, from solemn attestation, ἐπιμαρτύρασθαι. Any resumed undertaking should therefore be described as an attestation or commitment, not as an explicitly expressed ὀμνύω construction."
    },
    {
      "section": "1",
      "observation": "The instructional passage contains infinitives, including μὴ ὁρκίσαι and κελεῦσαι. This establishes that infinitival instructions occur in the supplied text, but not that an infinitive can automatically replace a first-person finite undertaking inside the subsequent attestation."
    },
    {
      "section": "1",
      "observation": "τοῦ μὴ ἁμαρτεῖν χάριν is a directly supplied example of χάριν governing a genitive articulated infinitive. It is not grammatically identical to τοῦδε μὴ μεταδοῦναι χάριν: τοῦδε is a demonstrative, not the article τοῦ."
    },
    {
      "section": "2",
      "observation": "λεγέτω introduces the attestation. Μάρτυρας ἔχοιμι is followed by ὡς ἀεὶ ὑπήκοος ἔσομαι and οὐ μὴ μεταδῶ. These establish the speaker and the undertaking, but their expressed syntax is principally finite."
    },
    {
      "section": "2",
      "observation": "The exception permits transmission to a tested, worthy recipient, with episcopal approval. Section 3's ἄλλως naturally contrasts other circumstances with that authorized exception."
    },
    {
      "section": "3",
      "observation": "The following finite commitments—φοβηθήσομαι, κολακευθήσομαι, μεταδώσω, ἀποδώσω, and the custody provisions—strongly support continued first-person commitment. They support the intended refusal to transmit to an unworthy relative, but do not independently establish the opening sentence's syntax."
    }
  ],
  "token_parse": [
    {
      "position": 1,
      "token": "ἄλλως",
      "morphology": "Adverb.",
      "attachment": "Frames the sentence as applying otherwise than under the authorized conditions in section 2."
    },
    {
      "position": 2,
      "token": "δὲ",
      "morphology": "Postpositive connective particle.",
      "attachment": "Connects and contrasts the new undertaking with the preceding exception."
    },
    {
      "position": 3,
      "token": "οὐδ’",
      "morphology": "Printed elision of οὐδέ.",
      "attachment": "Negative scalar expression, potentially 'not even'. Its governing construction and relationship to μή require testing; it cannot be discarded."
    },
    {
      "position": 4,
      "token": "ἂν",
      "morphology": "Particle with two relevant possible analyses: conditional ἄν, equivalent in function to ἐάν; or modal ἄν.",
      "attachment": "Conditional analysis requires an understood subjunctive predicate. Modal analysis requires an appropriate potential construction and cannot itself supply 'if'."
    },
    {
      "position": 5,
      "token": "τέκνον",
      "morphology": "Neuter singular, nominative or accusative in form.",
      "attachment": "The coordination with ἀδελφὸς and φίλος favors a nominative predicate description of the prospective recipient, not a dative recipient of μεταδοῦναι."
    },
    {
      "position": 6,
      "token": "ἢ",
      "morphology": "Disjunctive conjunction.",
      "attachment": "Coordinates τέκνον and ἀδελφὸς."
    },
    {
      "position": 7,
      "token": "ἀδελφὸς",
      "morphology": "Masculine nominative singular.",
      "attachment": "A coordinated nominative description; requires a construction admitting the nominative, such as an omitted copula."
    },
    {
      "position": 8,
      "token": "ἢ",
      "morphology": "Disjunctive conjunction.",
      "attachment": "Coordinates ἀδελφὸς and φίλος."
    },
    {
      "position": 9,
      "token": "φίλος",
      "morphology": "Masculine nominative singular.",
      "attachment": "Another coordinated nominative description."
    },
    {
      "position": 10,
      "token": "ἢ",
      "morphology": "Disjunctive conjunction.",
      "attachment": "Introduces the broader description ending in ἀνήκων."
    },
    {
      "position": 11,
      "token": "ἄλλως",
      "morphology": "Adverb.",
      "attachment": "Modifies the manner of the relationship expressed by ἀνήκων."
    },
    {
      "position": 12,
      "token": "πως",
      "morphology": "Indefinite adverb.",
      "attachment": "With ἄλλως, broadens the manner of relationship."
    },
    {
      "position": 13,
      "token": "ποτὲ",
      "morphology": "Indefinite temporal adverb.",
      "attachment": "Broadens the description: someone related at any time or ever. Its precise idiomatic force is not independently established."
    },
    {
      "position": 14,
      "token": "γένους",
      "morphology": "Genitive neuter singular of γένος.",
      "attachment": "Provisionally a genitive specifying the family or kinship domain of ἀνήκων. The exact construction needs corroboration; it must not silently become the dative γένει."
    },
    {
      "position": 15,
      "token": "μοι",
      "morphology": "First-person singular dative pronoun.",
      "attachment": "Relational dative with ἀνήκων: the relationship is to the speaker."
    },
    {
      "position": 16,
      "token": "ἀνήκων",
      "morphology": "Present active participle, masculine nominative singular, of ἀνήκω.",
      "attachment": "Completes the last coordinated nominative description. Under the concessive analysis it is predicative with an understood copula."
    },
    {
      "position": 17,
      "token": "ἐάνπερ",
      "morphology": "Conditional conjunction ἐάν strengthened by περ.",
      "attachment": "Introduces the expressed condition whose predicate is ἀνάξιος ᾖ."
    },
    {
      "position": 18,
      "token": "ἀνάξιος",
      "morphology": "Masculine nominative singular adjective.",
      "attachment": "Predicate adjective with ᾖ, describing the prospective recipient."
    },
    {
      "position": 19,
      "token": "ᾖ",
      "morphology": "Present active subjunctive, third-person singular, of εἰμί.",
      "attachment": "Expressed copula governed by ἐάνπερ. It also provides a nearby contextual model for an earlier omitted copula, without proving that omission."
    },
    {
      "position": 20,
      "token": "τοῦδε",
      "morphology": "Genitive masculine or neuter singular of the demonstrative ὅδε.",
      "attachment": "Leading possibility: masculine, referring to the unworthy person and governed by postpositional χάριν. Alternative: neuter, a partitive complement of μεταδοῦναι. It is not the genitive article introducing an infinitive."
    },
    {
      "position": 21,
      "token": "μὴ",
      "morphology": "Negative particle.",
      "attachment": "Negates μεταδοῦναι under an undertaking or prescriptive infinitive analysis. Its interaction with οὐδέ is unresolved."
    },
    {
      "position": 22,
      "token": "μεταδοῦναι",
      "morphology": "Second-aorist active infinitive of μεταδίδωμι.",
      "attachment": "Possible resumed commitment not to transmit. Its subject would be the speaker; its understood transmitted object would be the books. Neither an immediately governing undertaking verb nor an independent infinitive construction is expressly supplied here."
    },
    {
      "position": 23,
      "token": "χάριν",
      "morphology": "Accusative singular of χάρις; potentially functioning as a postposition governing a genitive.",
      "attachment": "Leading possibility: governs τοῦδε across μὴ μεταδοῦναι. Alternatives treating it as the verb's object or as an adverbial accusative must establish their own syntax and meaning."
    },
    {
      "position": 24,
      "token": "ὡς",
      "morphology": "Conjunction or explanatory particle.",
      "attachment": "Provisionally introduces the explanation for refusing transmission: the contemplated transmission was not fitting."
    },
    {
      "position": 25,
      "token": "οὐ",
      "morphology": "Negative particle.",
      "attachment": "Negates προσῆκεν. The act evaluated as unfitting must be transmission, not the already negated act of refraining from transmission."
    },
    {
      "position": 26,
      "token": "προσῆκεν",
      "morphology": "On the contextual impersonal reading, third-person singular imperfect active indicative of προσήκω.",
      "attachment": "Impersonal predicate of appropriateness, with the contemplated act supplied from context. Its printed tense must not be silently parsed as present."
    }
  ],
  "candidate_analyses": [
    {
      "id": "A",
      "name": "Resumed undertaking-infinitive, elliptical concession, and discontinuous τοῦδε ... χάριν",
      "confidence": "Moderate as a hypothesis; insufficient for an established reading.",
      "text_altered": false,
      "exact_attachments": {
        "ἄν": "Conditional particle governing an understood ᾖ.",
        "nominatives": "τέκνον, ἀδελφὸς, φίλος, and ἀνήκων are coordinated predicates of the prospective recipient under that omitted copula.",
        "ἐάνπερ_ἀνάξιος_ᾖ": "An additional condition restricting the refusal to an unworthy recipient.",
        "τοῦδε": "Masculine demonstrative referring to that recipient; genitive governed by χάριν.",
        "χάριν": "Postposition forming the discontinuous constituent τοῦδε ... χάριν, 'for this person's sake'.",
        "μεταδοῦναι": "Resumptive statement of the speaker's solemn commitment; transmitted object supplied from the books previously mentioned.",
        "μή": "Negation of the committed act of transmission.",
        "οὐδέ": "Proposed scalar reinforcement: even close relationship does not create an exception to the refusal.",
        "ὡς_οὐ_προσῆκεν": "Explanation of the refusal, evaluating affirmative transmission to the unworthy person as unfitting."
      },
      "elisions": {
        "printed_phonological_elision": "οὐδ’ represents οὐδέ.",
        "ordinary_contextual_ellipsis_proposed": [
          "A copula ᾖ in the first conditional phrase, recoverable by comparison with the following expressed ᾖ.",
          "The books as the unexpressed object of μεταδοῦναι.",
          "The contemplated act of transmission as what was not fitting."
        ],
        "constructional_assumption": "The infinitive resumes the undertaking without a newly expressed governing verb, or uses an independently available promissory/prescriptive construction.",
        "emendation": "None. Bracketed explanatory supplements are not additions to the printed text."
      },
      "tests": [
        "Case accounting succeeds provisionally: the nominatives belong to a copular clause, τοῦδε is governed by χάριν, and μοι and γένους belong to the relationship description.",
        "The personal antecedent of masculine τοῦδε is immediately available; no singular collective label for the books is needed.",
        "The discontinuity of τοῦδε ... χάριν is syntactically conceivable, but the section 1 example establishes a different construction and does not prove this hyperbaton.",
        "A solemn undertaking supplies discourse continuity, but an expressed finite commitment is not automatically a grammatical governor of a later infinitive.",
        "οὐδέ and μή must express one refusal with scalar reinforcement, not an outer negation of the negative infinitive."
      ],
      "weaknesses": [
        "The infinitival restart remains unverified in this precise attestation structure.",
        "The proposed negative relationship is not established merely by paraphrasing οὐδέ as 'not even'. Treating οὐδέ as negating μή μεταδοῦναι would reverse the intended refusal.",
        "The postpositional hyperbaton needs corroboration.",
        "The exact genitive construction in γένους μοι ἀνήκων remains provisionally classified."
      ]
    },
    {
      "id": "B",
      "name": "Elliptical finite refusal followed by an infinitival restatement",
      "confidence": "Low to moderate.",
      "text_altered": false,
      "exact_attachments": {
        "οὐδέ": "Negates an understood first-person finite verb of transmission.",
        "ἄν_and_nominatives": "As in A: conditional ἄν with an omitted copula and nominative predicates.",
        "τοῦδε_and_χάριν": "As in A: personal genitive governed by postpositional χάριν.",
        "μή_μεταδοῦναι": "A separate infinitival restatement of the refusal, rather than the immediate predicate negated by οὐδέ.",
        "ὡς_οὐ_προσῆκεν": "Explains why transmission is refused."
      },
      "elisions": {
        "printed_phonological_elision": "οὐδ’ represents οὐδέ.",
        "ordinary_contextual_ellipsis_proposed": [
          "An understood μεταδώσω, recoverable from section 2 and the following commitments.",
          "An omitted copula in the concessive phrase.",
          "The books as transmitted object."
        ],
        "constructional_assumption": "The infinitive can stand as a resumptive or explanatory formulation after the elliptical finite refusal.",
        "emendation": "None if these are strictly analytical supplements; inserting the supplied words into the Greek would instead create an edited reconstruction."
      },
      "tests": [
        "This gives οὐδέ a finite predicate and avoids making it negate the negative infinitive.",
        "Both negative expressions can concern the same refusal, because the infinitive restates rather than reverses the first assertion.",
        "The nearby finite transmission language supplies a plausible omitted verb."
      ],
      "weaknesses": [
        "It requires more unexpressed structure than A.",
        "The resulting finite-refusal-plus-infinitival-restatement sequence is not demonstrated by the supplied text.",
        "Recovering a verb from context is plausible; asserting a particular two-clause architecture is a stronger hypothesis."
      ]
    },
    {
      "id": "C",
      "name": "Modal ἄν with an omitted potential predicate",
      "confidence": "Low; no satisfactory complete construction identified.",
      "text_altered": false,
      "exact_attachments": {
        "ἄν": "Modal particle associated with an omitted potential predicate.",
        "nominatives": "Would have to be subjects or predicates within that potential clause.",
        "τοῦδε_and_χάριν": "Could retain A's postpositional attachment.",
        "μή_μεταδοῦναι": "Would still require a distinct infinitival construction."
      },
      "elisions": {
        "syntactic_ellipsis_required": "An appropriate potential predicate, not merely the subjunctive copula of the conditional analysis.",
        "emendation": "None proposed."
      },
      "tests": [
        "Modal ἄν does not itself mean 'even if'.",
        "Supplying only a potential copula yields a statement about whether someone would be a child, brother, or friend, not automatically a concession about an acknowledged relationship.",
        "Supplying a predicate such as persuading or inducing introduces additional semantic content and can produce the wrong relationship to μή μεταδοῦναι."
      ],
      "weaknesses": [
        "No economical omitted predicate has been identified that establishes the desired concession and accounts for both negatives.",
        "A familiar intended meaning cannot justify inventing the missing predicate."
      ]
    },
    {
      "id": "D",
      "name": "τοῦδε as partitive complement of μεταδοῦναι; χάριν as an adverbial accusative",
      "confidence": "Low.",
      "text_altered": false,
      "exact_attachments": {
        "τοῦδε": "Neuter genitive complement of μεταδοῦναι: sharing some of 'this'.",
        "μεταδοῦναι": "Negated undertaking-infinitive.",
        "χάριν": "Proposed adverbial accusative, intended to mean 'as a favor'.",
        "opening_concession": "Would require A's or B's treatment."
      },
      "elisions": {
        "contextual_referent_required": "A singular demonstrative referent for material previously described as plural books.",
        "emendation": "None."
      },
      "tests": [
        "A partitive genitive with a verb of sharing is a coherent grammatical possibility.",
        "That possibility does not simultaneously establish an independent adverbial use of χάριν meaning 'as a favor'.",
        "Taking χάριν as the postposition instead would move τοῦδε away from the verb and produce A, not this analysis."
      ],
      "weaknesses": [
        "The crucial adverbial construction and its intended meaning are unsupported by the supplied examples.",
        "The singular demonstrative's content-reference is less immediate than reference to the singular person.",
        "This is precisely why 'any of this as a favor' cannot be accepted merely by combining two individually attractive glosses."
      ]
    },
    {
      "id": "E",
      "name": "χάριν as the direct object, with τοῦδε modifying that noun",
      "confidence": "Low; formally possible but contextually weak.",
      "text_altered": false,
      "exact_attachments": {
        "χάριν": "Accusative object of μεταδοῦναι.",
        "τοῦδε": "Genitive dependent on the noun χάριν, provisionally possessive.",
        "μή": "Negates sharing or imparting that favor.",
        "opening_concession": "Would require A's or B's treatment."
      },
      "elisions": {
        "syntactic_ellipsis": "The same concessive and undertaking assumptions as A or B.",
        "emendation": "None."
      },
      "tests": [
        "The supplied transmission language admits accusative objects, so an accusative object is not excluded merely by the verb's form.",
        "A possessive genitive would concern this person's favor or grace; it does not straightforwardly make the person the recipient of a favor.",
        "The immediate context concerns transmission of books, not distribution of an unworthy person's favor."
      ],
      "weaknesses": [
        "It changes the lexical object of the undertaking away from the books.",
        "The relevant sense and construction of μεταδοῦναι χάριν need evidence.",
        "Interpreting the genitive directly as 'a favor to him' would require additional justification."
      ]
    },
    {
      "id": "F",
      "name": "Purpose phrase modeled directly on τοῦ μὴ ἁμαρτεῖν χάριν",
      "confidence": "Rejected as an established unchanged-text analysis.",
      "text_altered": false,
      "exact_attachments": {
        "proposed_attachment": "χάριν would govern an alleged genitive nominal infinitive μὴ μεταδοῦναι.",
        "problem": "The printed τοῦδε is not the article τοῦ and does not straightforwardly supply the required genitive articulation of that infinitive."
      },
      "elisions": {
        "unsupported_supplement": "Treating τοῦδε as determining a separately understood articulated infinitive would require additional justification, not merely contextual recovery of the books.",
        "conjectural_emendations_not_adopted": [
          "Replacing τοῦδε with τοῦ changes the printed word.",
          "Dividing τοῦδε into τοῦ δὲ changes the printed word division and grammatical identity."
        ]
      },
      "tests": [
        "Section 1 makes the articulated-infinitive construction visible and therefore helps expose, rather than erase, the difference.",
        "Even either textual alteration would not automatically solve the opening οὐδ’ ἂν and its nominatives."
      ],
      "weaknesses": [
        "It cannot be justified by silently reading the demonstrative as an article.",
        "The apparent local parallel is insufficient to authorize a textual repair."
      ]
    }
  ],
  "ellipsis_vs_emendation": {
    "ordinary_contextual_ellipsis": [
      "An omitted copula in a clearly established copular clause.",
      "Previously identified books as an omitted verbal object.",
      "A previously mentioned action as the contextual content evaluated by an impersonal predicate."
    ],
    "hypothesized_but_not_automatically_ordinary": [
      "A resumed infinitival undertaking after finite attestation formulas.",
      "An additional omitted finite refusal followed by an infinitival restatement.",
      "A potential predicate invented to make modal ἄν concessive."
    ],
    "conjectural_emendation": [
      "Changing τοῦδε to τοῦ.",
      "Changing the word division to τοῦ δὲ.",
      "Changing the nominative relationship terms into datives.",
      "Deleting or replacing either οὐδέ or μή."
    ],
    "principle": "A syntactic hypothesis can posit unexpressed material without editing the text, but calling it ellipsis does not establish that the construction is ordinary. Actual changes to letters, word division, forms, or negation are textual conjectures."
  },
  "defensible_reading_or_null": null,
  "additional_evidence_needed": [
    {
      "priority": 1,
      "question": "Can an infinitive resume a solemn attestation framed by Μάρτυρας ἔχοιμι and finite ὡς clauses?",
      "needed": "Exact Greek parallels showing the relevant finite-to-infinitival transition, preferably with first-person commitments and μή."
    },
    {
      "priority": 1,
      "question": "Can οὐδ’ ἄν introduce this elliptical concession alongside a negative undertaking-infinitive?",
      "needed": "Parallels establishing conditional ἄν, omitted copula, and the scope relationship between οὐδέ and μή without a negative reversal."
    },
    {
      "priority": 2,
      "question": "Can τοῦδε and postpositional χάριν enclose μὴ μεταδοῦναι here?",
      "needed": "Examples of χάριν governing a personal genitive separated from it by a substantive verbal constituent. Section 1's articulated infinitive is not an exact parallel."
    },
    {
      "priority": 2,
      "question": "What precisely licenses γένους μοι ἀνήκων?",
      "needed": "Examples establishing the genitive's relationship to ἀνήκων and the dative's relational function."
    },
    {
      "priority": 3,
      "question": "Do the alternative accusative analyses of χάριν have the required lexical force?",
      "needed": "Evidence for bare adverbial χάριν meaning 'as a favor', or for μεταδοῦναι χάριν with the proposed genitive modifier."
    },
    {
      "priority": 3,
      "question": "Is there independent textual evidence relevant to the impasse?",
      "needed": "Any supplied apparatus, alternative witness, or explicitly argued editorial discussion. Such evidence could inform a separate textual inquiry; the present syntactic difficulty alone does not establish corruption."
    }
  ]
